"use server";

import { z } from "zod";
import { refresh, updateTag } from "next/cache";
import { db } from "@/lib/db";
import { requireUser, hashPassword, verifyPassword } from "@/lib/auth";
import { destroyAllSessions, createSession } from "@/lib/session";
import { rateLimit } from "@/lib/security";
import { razorpay } from "@/lib/razorpay";
import { after } from "next/server";
import { sendCancellation } from "@/lib/email";
import { TAGS } from "@/lib/tags";
import { addressSchema } from "@/lib/validators";
import type { FormState } from "./auth";

export async function deleteAddress(id: string) {
  const user = await requireUser();
  await db.address.deleteMany({ where: { id, userId: user.id } });
  refresh();
}

export async function saveAddress(_: FormState, formData: FormData): Promise<FormState> {
  const user = await requireUser();
  const parsed = addressSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors };
  if ((await db.address.count({ where: { userId: user.id } })) >= 10) return { error: "You can save up to 10 addresses." };
  await db.address.create({ data: { ...parsed.data, userId: user.id } });
  refresh();
  return { ok: true };
}

const passwordSchema = z.object({
  current: z.string().min(1),
  next: z.string().min(8, "Use at least 8 characters").max(128).regex(/[A-Za-z]/, "Include a letter").regex(/\d/, "Include a number"),
});

export async function changePassword(_: FormState, formData: FormData): Promise<FormState> {
  const user = await requireUser();
  if (!(await rateLimit("pwd", 5, 15 * 60))) return { error: "Too many attempts. Try again later." };
  const parsed = passwordSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { fieldErrors: parsed.error.flatten().fieldErrors };
  const record = await db.user.findUniqueOrThrow({ where: { id: user.id } });
  if (!(await verifyPassword(parsed.data.current, record.passwordHash))) return { fieldErrors: { current: ["Current password is incorrect"] } };
  await db.user.update({ where: { id: user.id }, data: { passwordHash: await hashPassword(parsed.data.next) } });
  // Sign out every other device.
  await destroyAllSessions(user.id);
  await createSession(user.id);
  return { ok: true };
}

const reviewSchema = z.object({
  productId: z.string().min(1).max(40),
  rating: z.coerce.number().int().min(1).max(5),
  title: z.string().trim().max(120).optional(),
  body: z.string().trim().max(2000).optional(),
});

export async function submitReview(_: FormState, formData: FormData): Promise<FormState> {
  const user = await requireUser();
  if (!(await rateLimit("review", 10, 60 * 60))) return { error: "Too many reviews. Try again later." };
  const parsed = reviewSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) return { error: "Please choose a rating." };
  const { productId, ...rest } = parsed.data;
  const product = await db.product.findUnique({ where: { id: productId }, select: { slug: true } });
  if (!product) return { error: "Product not found." };
  const purchased = await db.orderItem.count({ where: { productId, order: { userId: user.id, paidAt: { not: null } } } });
  await db.review.upsert({
    where: { productId_userId: { productId, userId: user.id } },
    create: { productId, userId: user.id, ...rest, verifiedPurchase: purchased > 0 },
    update: { ...rest, verifiedPurchase: purchased > 0 },
  });
  const agg = await db.review.aggregate({ where: { productId, isApproved: true }, _avg: { rating: true }, _count: true });
  await db.product.update({ where: { id: productId }, data: { ratingAvg: agg._avg.rating ?? 0, ratingCount: agg._count } });
  updateTag(TAGS.reviews(productId));
  updateTag(TAGS.product(product.slug));
  return { ok: true };
}

/**
 * Customer self-service cancellation. Allowed only while the order is PAID (not yet being packed).
 * Restocks items and issues a full Razorpay refund automatically.
 */
export async function cancelMyOrder(_: FormState, formData: FormData): Promise<FormState> {
  const user = await requireUser();
  if (!(await rateLimit("cancel", 5, 60 * 60))) return { error: "Too many attempts. Please contact us on WhatsApp." };
  const orderNumber = String(formData.get("orderNumber") ?? "");
  const reason = String(formData.get("reason") ?? "").trim().slice(0, 300);
  const order = await db.order.findUnique({ where: { orderNumber }, include: { items: true } });
  if (!order || order.userId !== user.id) return { error: "Order not found." };
  if (order.status !== "PAID") return { error: "This order is already being processed and can’t be cancelled online. Please contact us." };

  // Claim the order first so a concurrent admin status change can't race the refund.
  const claimed = await db.order.updateMany({ where: { id: order.id, status: "PAID" }, data: { status: "CANCELLED" } });
  if (claimed.count === 0) return { error: "Order status changed. Please refresh." };

  let refundNote = "No online payment to refund";
  if (order.razorpayPaymentId) {
    try {
      const refund = await razorpay().payments.refund(order.razorpayPaymentId, { amount: order.total, notes: { orderNumber, reason: "customer_cancelled" } });
      refundNote = `Refund ₹${order.total / 100} initiated (${refund.id})`;
    } catch (err) {
      console.error("Customer cancel refund failed", orderNumber, err);
      await db.order.update({ where: { id: order.id }, data: { status: "PAID" } });
      return { error: "We couldn’t start the refund automatically. Your order is unchanged — please contact us and we’ll cancel it for you." };
    }
  }

  await db.$transaction(async (tx) => {
    if (order.stockCommitted) {
      for (const it of order.items) if (it.productId) await tx.product.update({ where: { id: it.productId }, data: { stock: { increment: it.quantity } } });
    }
    await tx.order.update({
      where: { id: order.id },
      data: {
        stockCommitted: false,
        events: { create: [{ status: "CANCELLED", note: `Cancelled by customer${reason ? `: ${reason}` : ""}` }, { status: "REFUND_INITIATED", note: refundNote }] },
      },
    });
  });
  after(() => sendCancellation(order.id, refundNote));
  updateTag(TAGS.products);
  refresh();
  return { ok: true };
}
